import { TestRunner } from "vitest";
import type { Task } from "vitest";

function fullName(task: Task): string {
  return task.suite && task.suite.name ? `${fullName(task.suite)} > ${task.name}` : task.name;
}

export default class TimingRunner extends TestRunner {
  override onAfterRunTask(test: Task) {
    super.onAfterRunTask(test);
    console.log(`TIMING ${fullName(test)} ${Math.round(test.result?.duration ?? 0)}`);
  }
}

